class Container:
    def __init__(self, cap):
        self.values = [None] * cap
        self.count = 0

    def expand(self, new_cap):
        new_vals = [None] * new_cap
        for i in range(self.count):
            new_vals[i] = self.values[i]
        self.values = new_vals

    def insert(self, idx, elem):
        if idx < 0 or idx > self.count:
            raise ValueError("Add failed. Require 0 <= index <= size.")

        if self.count == len(self.values):
            self.expand(2 * len(self.values))

        for i in range(self.count - 1, idx - 1, -1):
            self.values[i + 1] = self.values[i]

        self.values[idx] = elem
        self.count += 1

def obtain(self, pos):
    if pos < 0 or pos >= self.length:
        raise ValueError("Get failed. Index is illegal.")
    return self.storage[pos]

def includes(self, elem):
    for i in range(self.count):
        if self.values[i] == elem:
            return True
    return False

def locate(self, elem):
    for i in range(self.count):
        if self.values[i] == elem:
            return i
    return -1

def __repr__(self):
    parts = []
    parts.append(f"Queue: size = {self.count} , capacity = {self.get_cap()}\n")
    parts.append("front [")
    idx = self.front
    while idx != self.tail:
        parts.append(str(self.values[idx]))
        idx = (idx + 1) % len(self.values)
        if idx != self.tail:
            parts.append(", ")
    parts.append("] tail")
    return "".join(parts)

