class BinaryTree:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

    def insert(self, node, elem):
        if elem < node.val:
            if node.left is None:
                node.left = BinaryTree(elem)
            else:
                self.insert(node.left, elem)
        else:
            if node.right is None:
                node.right = BinaryTree(elem)
            else:
                self.insert(node.right, elem)

