def build_tree(lst: list[dict]) -> None:
    if not lst:
        return

    for item in lst:
        child_num = item.get("childNum")
        if child_num is not None and int(child_num) > 0:
            children = get_tree_by_id(str(item.get("treeId")), True)
            build_tree(children)
            item["children"] = children

